const $=id=>document.getElementById(id),keys=['quote','cap','extras','deadline','claimRef','receipt','owner'];let ru=location.hash==='#ru',previous=null,secondState={...PactCase.secondDefaults};
const display=v=>window.pactDisplay?window.pactDisplay(String(v)):String(v);const t=(en,r)=>ru?r:en,fmt=n=>'€'+Number(n).toLocaleString(ru?'ru-RU':'en-GB',{maximumFractionDigits:2});
const presets={conflict:{...PactCase.defaults},approve:{...PactCase.defaults,extras:'approved',deadline:'accepted',claimRef:'ST-24'},withdraw:{...PactCase.defaults,extras:'withdrawn',deadline:'accepted',claimRef:'ST-25'}};
const stateNames=()=>({needs_approval:t('Extra work needs approval','Допработы требуют согласования'),approved:t('Extra work approved','Допработы согласованы'),withdrawn:t('Unapproved request withdrawn','Несогласованный запрос отозван'),cancellation_pending:t('Cancellation requires agreement','Отмена требует согласования')});
function getInput(){const x={};for(const k of keys){x[k]=['quote','cap','receipt'].includes(k)?Number($(k).value):$(k).value;if(['quote','cap','receipt'].includes(k)&&$(k).value==='')throw Error(t('Enter all amounts.','Заполните все суммы.'));}x.second={...secondState};return x;}
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function source(id,text){const a=node('a',text);a.href='#'+id;return a;}
function draw(reset=false){let x,r;try{x=getInput();r=PactCase.evaluate(x);$('error').textContent=''}catch(e){$('error').textContent=t('Not recalculated: ','Не пересчитано: ')+e.message;return;}
 if(window.pactChatOverlay?.decorate)r=window.pactChatOverlay.decorate(r);
 document.querySelectorAll('[data-preset]').forEach(b=>b.setAttribute('aria-pressed',String(keys.every(k=>x[k]===presets[b.dataset.preset][k]))));
 $('cards').replaceChildren();for(const c of r.cases){const card=node('section',undefined,'card');card.append(node('h2',($('client')?.value||'Rowan')+' / '+display(c.id)+' · '+(c.id==='ST-24'?t('Catalogue','Каталог'):t('Portraits','Портреты'))));card.append(node('p',`${c.images} ${t('images','изображений')} · ${t('Owner','Ответственный')}: ${c.owner} · ${t('Due','Срок')}: ${ru?({Thursday:'четверг',Friday:'пятница',Monday:'понедельник'}[c.date]):c.date}`));const metrics=node('div',undefined,'metrics');for(const [label,value] of [[t('Agreed value','Согласовано'),fmt(c.total)],[t('Receipt fixture','Поступление в модели'),fmt(c.receipt)],[t('Unpaid balance¹','Неоплаченный остаток¹'),fmt(c.outstanding)],[t('Client reports sent','Клиент заявил отправку'),c.claim===null?'—':fmt(c.claim)]]){const m=node('div',label,'metric');m.append(node('b',value));metrics.append(m)}card.append(metrics);if(c.unverifiedClaim!==null)card.append(node('p',t('Claim not corroborated: ','Не подтверждено по заявлению: ')+fmt(c.unverifiedClaim)));if(c.overpayment)card.append(node('p',t('Unallocated excess receipt: ','Излишек поступления: ')+fmt(c.overpayment)));if(c.id==='ST-24'){card.append(node('p',stateNames()[c.extraState],'badge'));card.append(node('p',c.datePending?t('Thursday is requested, not agreed. Friday remains the agreed date.','Четверг запрошен, но не согласован. Согласованный срок — пятница.'):t('Thursday is confirmed by both sides.','Четверг подтверждён обеими сторонами.')));const p=node('p');p.append(source(r.extraBasis,t('Scope basis','Основание объёма')),document.createTextNode(' · '),source(r.dateBasis,t('Date basis','Основание срока')),document.createTextNode(' · '),source('e9',t('Receipt fixture','Модель поступления')));card.append(p)}else{card.append(node('p',stateNames()[c.extraState],'badge'));card.append(node('p',c.datePending?t('Thursday is requested; Monday remains agreed.','Четверг запрошен; согласован понедельник.'):t('Thursday is confirmed.','Четверг подтверждён.')));const p=node('p');p.append(source(c.scopeSource||'e2b',t('Scope basis','Основание объёма')),document.createTextNode(' · '),source(c.dateSource||'e2',t('Date basis','Основание срока')));card.append(p);}card.append(node('p',t('¹Balance only; this does not establish an overdue debt.','¹Остаток суммы, а не утверждение о просроченной задолженности.'),'muted'));$('cards').append(card)}
 const alerts={reference:t('Ask which order the EUR 300 claim refers to. Do not allocate it twice.','Уточнить, к какому заказу относятся заявленные 300 евро. Не учитывать их дважды.'),scope:t('The quote exceeds the authorized limit. Obtain explicit extra-work approval.','Цена выше разрешённого лимита. Получить явное согласование допработ.'),deadline:t('Confirm the requested date with the studio; keep the previously agreed date until accepted.','Согласовать запрошенный срок со студией; до этого сохранить прежний согласованный срок.'),receipt:t('Reconcile the payment claim with receipt evidence for the named order.','Сверить заявление об оплате с поступлением по указанному заказу.'),overpayment:t('Resolve the excess receipt. Do not silently transfer it to another order.','Разобрать излишек поступления. Не переносить его молча на другой заказ.'),cancel:t('Extra work was already authorized within the limit. Agree cancellation before reducing the order.','Допработы уже разрешены в пределах лимита. Согласовать отмену до уменьшения заказа.')};$('alerts').replaceChildren();for(const a of r.alerts){const li=node('li',display(a.caseId||'ST-24')+' · '+alerts[a.code]+' ');li.append(source(a.source,t('Source →','Источник →')));$('alerts').append(li)}if(!r.alerts.length)$('alerts').append(node('li',t('No unresolved contradiction in this scenario. Review outstanding work and balances.','В сценарии нет неразрешённых противоречий. Проверьте оставшуюся работу и суммы.')));
 $('unallocated').textContent=r.unallocatedClaim?t('Unallocated client claim: ','Нераспределённое заявление клиента: ')+fmt(r.unallocatedClaim):t('The claim is attached to one order only; it is not a receipt.','Заявление связано только с одним заказом; это не поступление.');
 $('changes').replaceChildren();if(previous&&!reset){for(let i=0;i<2;i++)for(const [key,label] of [['total',t('agreed value','согласованная сумма')],['images',t('images','изображения')],['receipt',t('receipt fixture','модель поступления')],['claim',t('payment claim','заявление об оплате')],['date',t('agreed date','согласованный срок')],['owner',t('owner','ответственный')],['extraState',t('scope status','статус объёма')]]){const a=previous.cases[i][key],b=r.cases[i][key];if(a!==b)$('changes').append(node('li',`${display(r.cases[i].id)} · ${label}: ${key==='extraState'?(stateNames()[a]||a):(key==='date'&&ru?({Friday:'пятница',Thursday:'четверг',Monday:'понедельник'}[a]):(a??'—'))} → ${key==='extraState'?(stateNames()[b]||b):(key==='date'&&ru?({Friday:'пятница',Thursday:'четверг',Monday:'понедельник'}[b]):(b??'—'))}`));}if(previous.unallocatedClaim!==r.unallocatedClaim)$('changes').append(node('li',t('Unallocated claim','Нераспределённое заявление')+`: ${previous.unallocatedClaim} → ${r.unallocatedClaim}`));if(!$('changes').children.length)$('changes').append(node('li',t('Evidence updated; agreed amounts and ownership did not change.','Доказательства обновлены; согласованные суммы и ответственность не изменились.')))}else $('changes').append(node('li',t('Starting state. Change a control to see its effect.','Исходное состояние. Измените условие, чтобы увидеть последствия.')));
 if(window.pactChatOverlay){r.events=window.pactChatOverlay.events(r.events);}
 $('events').replaceChildren();for(const e of r.events){const li=node('li');li.id=e.id;li.append(node('b',`${e.time} · ${e.channel} · ${e.who==='Rowan'?($('client')?.value||'Rowan'):e.who}`));li.append(node('p',display(e.text)));$('events').append(li)}previous=r;
}
function language(){document.documentElement.lang=ru?'ru':'en';$('lang').textContent=ru?'English':'Русский';const map={back:['← Case overview','← Обзор дел'],story:['Article','Статья'],lab:['AI model lab','Лаборатория ИИ'],eyebrow:['INTERACTIVE DECISION CHALLENGE','ИНТЕРАКТИВНАЯ ПРОВЕРКА РЕШЕНИЙ'],title:['Messages change. See exactly what changes in the case.','Переписка меняется. Проверьте, что меняется в деле.'],intro:['Change a message’s structured meaning. Watch the agreement, balance and next action recompute—and inspect the source.','Изменяйте структурированные условия сообщения: договорённость, остаток и следующее действие пересчитаются. Каждый вывод можно сверить с источником.'],boundary:['Fictional data, including the receipt. Messages receive contextual evidence review and a separate model suggestion. Only supported, explicitly confirmed events change the case. Unsupported wording requires manual review. No accounts are connected.','Все данные вымышлены, включая поступление. Для сообщений показаны контекстный разбор и отдельная подсказка модели. Дело меняют только поддерживаемые события после явного подтверждения. Остальные формулировки требуют ручной проверки. Аккаунты не подключены.'],'edit-title':['Change the evidence','Измените исходные условия'],'cap-label':['Client’s extra-fee limit (EUR)','Лимит доплаты клиента (евро)'],'quote-label':['Studio’s extra-work quote (EUR)','Цена дополнительных работ (евро)'],'extras-label':['Client’s scope message','Сообщение клиента об объёме'],'deadline-label':['Thursday delivery','Срок — четверг'],'claim-label':['Order named in “sent EUR 300”','Заказ в сообщении «отправил 300 евро»'],'receipt-label':['Synthetic cumulative receipt for ST-24 (EUR)','Вымышленное поступление всего по ST-24 (евро)'],'owner-label':['ST-24 owner','Ответственный за ST-24'],note:['Amounts describe cumulative totals, not additional transfers. No messages or transactions are sent.','Суммы означают итоговые поступления, не новые переводы. Сообщения и транзакции не отправляются.'],reset:['Reset scenario','Сбросить сценарий'],'next-title':['Decisions needing attention','Какие решения нужны'],'changes-title':['What changed after your edit?','Что изменилось после вашей правки?'],'timeline-title':['One timeline, two separate orders','Одна хронология, два отдельных заказа'],'timeline-note':['English source fixtures update with your controls. Receipt evidence is explicitly simulated.','Исходные сообщения на английском обновляются вместе с условиями. Поступление явно обозначено как вымышленное.']};for(const [id,txt]of Object.entries(map))$(id).textContent=txt[ru?1:0];const options={extras:[['Conditional approval up to limit','Разрешение только в пределах лимита'],['Explicitly approve the quoted price','Явно согласовать предложенную цену'],['Withdraw the extra-work request','Отозвать запрос на допработы']],deadline:[['Requested by client only','Только просьба клиента'],['Confirmed by studio too','Студия тоже подтвердила']],claimRef:[['Not specified','Не указан'],['ST-24 · Catalogue','ST-24 · Каталог'],['ST-25 · Portraits','ST-25 · Портреты']]};for(const[k,rows]of Object.entries(options))rows.forEach((v,i)=>$(k).options[i].textContent=v[ru?1:0]);document.querySelectorAll('[data-preset]').forEach((b,i)=>b.textContent=(i+1)+' · '+(ru?['Противоречие','Согласование','Отзыв запроса']:['Conflict','Approval','Withdraw request'])[i]);draw(true);}
function apply(v){secondState={...PactCase.secondDefaults,...v.second};for(const k of keys)$(k).value=v[k];draw();}
keys.forEach(k=>$(k).addEventListener('input',()=>draw()));document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>apply(presets[b.dataset.preset]));$('reset').onclick=()=>{previous=null;apply(PactCase.defaults)};$('lang').onclick=()=>{ru=!ru;history.replaceState(null,'',ru?'#ru':'#en');language();if(window.pactLocalize)window.pactLocalize()};language();

window.pactScenario={getInput,apply,draw,resetPrevious:()=>{previous=null}};
